import * as React from "react";
import type { HoverCardProps } from "@/components/hover-card";

/**
 * Token categories shown in the context usage details.
 */
export interface TokenUsageBreakdown {
  /** Tokens attributed to the prompt and prior conversation. */
  inputTokens?: number;
  /** Tokens generated by the model. */
  outputTokens?: number;
  /** Tokens attributed to model reasoning. */
  reasoningTokens?: number;
  /** Tokens served from the model's cache. */
  cachedTokens?: number;
}

/**
 * Props for the legacy inline context usage gauge.
 */
export interface ContextUsageProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Tokens currently used. */
  usedTokens: number;
  /** Maximum context window limit. */
  maxTokens: number;
  /** Optional detailed breakdown of token consumption. */
  breakdown?: TokenUsageBreakdown;
  /** Model or context label, for example "Model context". */
  label?: string;
  /** Compact or regular gauge sizing. */
  size?: "sm" | "md";
}

/**
 * Props for the Context hover-card root.
 */
export interface ContextProps extends Omit<HoverCardProps, "children"> {
  /** Child trigger and content parts. */
  children?: React.ReactNode;
  /** Total tokens currently used in the context window. */
  usedTokens: number;
  /** Maximum supported context window size. */
  maxTokens: number;
  /** Optional breakdown of usage by token category. */
  usage?: TokenUsageBreakdown;
  /** Optional model identifier displayed in the details panel. */
  modelId?: string;
}

/**
 * Props for the context usage trigger.
 */
export interface ContextTriggerProps extends Omit<
  React.ButtonHTMLAttributes<HTMLButtonElement>,
  "children"
> {
  /** Optional trigger label; defaults to the formatted context percentage. */
  children?: React.ReactNode;
}

/**
 * Props for a Context hover-card content region.
 */
/**
 * Props for a Context hover-card content region.
 */
export type ContextContentProps = React.HTMLAttributes<HTMLDivElement>;
